head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getTimeoutKeyList]<br/>setTimeout() 메소드로 등록된 Timeout 객체의 키 값을 배열로 반환합니다.",
    "validation" : [
        "등록된 Timeout 객체의 키 문자열 배열을 반환해야 합니다.",
        "등록된 Timeout 이 없으면 빈 배열([])을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_setTimeout_onclick = function () {
    $p.setTimeout(function () {}, {key: "timeout_A", delay: 10000});
    $p.setTimeout(function () {}, {key: "timeout_B", delay: 10000});

    wf_body_bottom.getObj("scwin").setReturnValue("setTimeout 등록 완료 (timeout_A, timeout_B)");
}



scwin.btn_getTimeoutKeyList_onclick = function () {
    var keyList = $p.getTimeoutKeyList();

    wf_body_bottom.getObj("scwin").setReturnValue("배열 길이 : " + keyList.length + ", 키 목록 : [" + keyList.join(", ") + "]");
}



scwin.btn_clearAll_onclick = function () {
    var keyList = $p.getTimeoutKeyList();
    for (var i = 0; i < keyList.length; i++) {
        $p.clearTimeout(keyList[i]);
    }

    var afterList = $p.getTimeoutKeyList();
    wf_body_bottom.getObj("scwin").setReturnValue("전체 제거 완료, 남은 타이머 : " + afterList.length + "개");
}
